const put=(id,de,es,it,fr,zh)=>{review[industryInterfaceCopy[id]]={de,es,it,fr,zh};};
put('function','Baugruppenfunktion','Función en el conjunto','Funzione nell’assieme','Fonction dans l’assemblage','装配功能');
put('spec','Mit den Gegenstücken spezifizieren','Definir junto con las piezas acopladas','Specificare insieme ai pezzi accoppiati','À spécifier avec les pièces en regard','结合配合件明确的要求');
put('acceptance','Abnahme und weitere Prüfung','Aceptación y siguiente revisión','Accettazione e verifica successiva','Réception et examen suivant','验收及后续评审');
put('qualityLink','Funktionsprüfungen und Nachweise planen','Planificar pruebas funcionales y registros','Pianificare prove funzionali e documenti','Prévoir les essais fonctionnels et leurs documents','制定功能试验与记录要求');
put('note','Konstruktionsbeispiele, keine Kundenauslieferungsberichte. Grenzwerte und Prüfungen für die bestellte Baugruppe festlegen.','Ejemplos de revisión de diseño, no registros de entregas a clientes. Defina límites y controles para el conjunto pedido.','Esempi di revisione progettuale, non documenti di consegne a clienti. Definire limiti e controlli per l’assieme ordinato.','Exemples de revue de conception, pas des dossiers de livraison client. Définissez limites et contrôles pour l’assemblage commandé.','以上为设计评审示例，并非客户交付记录。实际限值和检查项目应针对所订购的装配确定。');
put('automationMetaTitle','Sonderbefestiger für die Industrieautomation','Fijaciones a medida para automatización industrial','Elementi di fissaggio per automazione industriale','Fixations sur mesure pour l’automatisation industrielle','工业自动化非标螺丝：转动、定位与调节');
put('automationMeta','Schraubenschnittstellen für Drehgelenke, Positionierung und Verstellung vergleichen. Gegenstückgeometrie mit Produkten, Fertigungswegen und Prüfnachweisen verbinden.','Compare interfaces de giro, posicionamiento y ajuste en automatización. Relacione geometría acoplada, productos, procesos y registros de aceptación.','Confrontare interfacce di rotazione, posizionamento e regolazione. Collegare geometria accoppiata, prodotti, cicli e documenti di accettazione.','Comparez les interfaces de pivot, de positionnement et de réglage en automatisation, avec produits, procédés et documents de réception adaptés.','比较自动化机构中转动、定位和调节所需的螺丝接口，从配合件几何找到对应产品、加工路线和验收记录。');
put('automationTitle','Drehen, Positionieren und Verstellen unterscheiden','Separar giro, posicionamiento y ajuste','Distinguere rotazione, posizionamento e regolazione','Distinguer pivotement, positionnement et réglage','先区分转动、定位与调节');
put('automationIntro','Ein Mechanismus kann dieselbe Gewindegröße für sehr unterschiedliche Aufgaben verwenden. Beginnen Sie mit der Fläche, die Bewegung oder Position bestimmt; definieren Sie dann, wie die Schraube die Baugruppe hält.','Un mecanismo puede usar la misma rosca para funciones muy distintas. Empiece por la superficie que determina movimiento o posición y defina después cómo retiene el tornillo el conjunto.','Un meccanismo può usare lo stesso filetto per compiti molto diversi. Partire dalla superficie che determina movimento o posizione, poi definire come la vite trattiene l’assieme.','Un mécanisme peut utiliser le même filetage pour des fonctions très différentes. Partez de la surface qui établit mouvement ou position, puis définissez le maintien de l’assemblage par la vis.','同样的螺纹规格，在机构里可能承担完全不同的任务。先找出决定运动或位置的表面，再明确螺丝怎样保持整个装配。');
put('automationOne','Drehgelenk auf glatter Schulter','Giro sobre un hombro liso','Rotazione su spallamento liscio','Pivotement sur un épaulement lisse','以光杆肩轴作为转轴');
put('automationOneSpec','Bohrungsgrenzen, fertigen Schulterdurchmesser, Kontaktlänge und Axialstapel zeigen. Drehfläche und Haltegewinde getrennt behandeln.','Indique límites del taladro, diámetro final del hombro, longitud de contacto y cadena axial. Separe el giro de la rosca de retención.','Indicare limiti del foro, diametro finito dello spallamento, lunghezza di contatto e catena assiale. Separare rotazione e filetto di ritegno.','Indiquez limites d’alésage, diamètre fini d’épaulement, longueur de contact et chaîne axiale. Séparez l’interface tournante du filetage de maintien.','标出孔径极限、成品肩轴直径、接触长度和轴向尺寸链，把转动配合与保持装配的螺纹分开定义。');
put('automationOneCheck','Bohrungs-Schulter-Spiel und freie Bewegung im montierten Stapel prüfen. Eine Gewindelehre allein nimmt das Drehgelenk nicht ab.','Compruebe holgura entre taladro y hombro y movimiento libre en el conjunto. El calibre de rosca no basta para aceptar el giro.','Controllare gioco foro-spallamento e movimento libero nell’assieme. Il solo controllo del filetto non accetta il perno rotante.','Vérifiez le jeu alésage-épaulement et la liberté de mouvement dans l’empilage monté. Le contrôle du filetage ne réceptionne pas le pivot.','核对孔轴间隙，并在实际轴向叠层中检查能否自由转动。螺纹通止规合格不能代替转动配合验收。');
put('automationTwo','Abnehmbare Station positionieren','Posicionar una estación desmontable','Posizionare una stazione rimovibile','Positionner un poste démontable','给可拆卸工位定位');
put('automationTwoSpec','Positionierstift, Gegenbohrung und Anlagefläche benennen. Bezugsbeziehungen und vorgesehene Abnahmerichtung zeigen.','Identifique pasador, orificio acoplado y cara de asiento. Indique relaciones de referencia y dirección prevista de desmontaje.','Identificare perno, foro accoppiato e piano d’appoggio. Indicare riferimenti geometrici e direzione di rimozione prevista.','Identifiez pion, trou en regard et face d’appui, avec relations de référence et direction de démontage prévue.','明确定位销、配合孔和落座面，标出它们的基准关系及预定拆卸方向。');
put('automationTwoCheck','Festgelegte Lagebeziehungen messen und Aus- und Wiedereinbau erproben. Das Spanngewinde ist nicht automatisch der Positionierbezug.','Mida las relaciones de posición y pruebe desmontaje y remontaje. La rosca de apriete no es automáticamente la referencia de posicionamiento.','Misurare le relazioni di posizione e provare rimozione e rimontaggio. Il filetto di serraggio non è automaticamente il riferimento di posizionamento.','Mesurez les relations de position spécifiées et essayez dépose et repose. Le filetage de serrage n’est pas automatiquement la référence de positionnement.','测量图纸规定的定位关系，并试装拆卸和复位。用于夹紧的螺纹不一定就是定位基准。');
put('automationThree','Anschlag oder Führung verstellen','Regular un tope o una guía','Regolare un arresto o una guida','Régler une butée ou un guidage','调节止挡或导向件');
put('automationThreeSpec','Hub, Kontaktende, zulässige Spuren und Halten der Einstellung festlegen. Hand- und Werkzeugfreiraum an beiden Hubenden berücksichtigen.','Defina recorrido, extremo de contacto, marcas admisibles y retención del ajuste. Incluya espacio de mano y herramienta en ambos extremos.','Definire corsa, estremità di contatto, segni ammessi e mantenimento della regolazione. Considerare spazio per operatore e utensile a fine corsa.','Définissez course, extrémité de contact, marques admises et maintien du réglage. Prévoyez accès opérateur et outil aux extrémités.','规定调节行程、接触端、允许压痕及位置保持方式，同时检查行程两端的手部和工具空间。');
put('automationThreeCheck','Einstellung vor und nach dem vereinbarten Verstellablauf dokumentieren. Sichtspuren, Positionsmessung und Halteprüfung unterscheiden.','Registre el ajuste antes y después de la secuencia acordada. Separe marcas visuales, medida de posición y comprobación de retención.','Registrare la posizione prima e dopo la sequenza concordata. Distinguere segni visivi, misura della posizione e controllo del mantenimento.','Consignez le réglage avant et après la séquence convenue. Distinguez marques visibles, mesure de position et maintien.','记录约定调节过程前后的位置，分别判断表面痕迹、位置测量和保持功能。');
put('automationCaseTitle','Änderungsbeispiel: eine Gelenkbuchse ersetzen','Ejemplo de cambio: sustituir un casquillo de giro','Esempio di modifica: sostituire una boccola del perno','Exemple de modification : remplacer une bague de pivot','变更示例：更换转轴衬套');
put('automationCase','Eine Ersatzbuchse kann Bohrungsgrenzen oder den wirksamen Axialstapel ändern, auch wenn die Schraube gleich bleibt. Vergleichen Sie neue Bohrung und Stapel mit den fertigen Schultergrenzen, danach Bewegung und Anlage. Verknüpfen Sie Buchsen- und Schraubenstand im Musterprotokoll. Die bisherige Freigabe gilt für ihre ursprüngliche Konfiguration; dokumentieren Sie die Prüfungen der geänderten Baugruppe.','Un casquillo nuevo puede cambiar los límites del taladro o la cadena axial efectiva aunque el tornillo no cambie. Compare taladro y cadena nuevos con los límites finales del hombro y revise movimiento y asiento. Vincule las revisiones de casquillo y tornillo en el registro de muestras. Conserve la aprobación anterior para su configuración original y documente los controles aplicables al conjunto revisado.','Una boccola sostitutiva può cambiare i limiti del foro o la catena assiale effettiva anche con la stessa vite. Confrontare nuovo foro e catena con i limiti dello spallamento finito, poi verificare movimento e appoggio. Collegare le revisioni di boccola e vite nel verbale dei campioni. Conservare l’approvazione precedente per la configurazione originale e documentare i controlli dell’assieme modificato.','Une bague de remplacement peut modifier les limites d’alésage ou la chaîne axiale effective sans changer la vis. Comparez nouvel alésage et empilage aux limites de l’épaulement fini, puis examinez mouvement et appui. Reliez les indices de bague et de vis au dossier d’échantillons. Conservez l’ancienne approbation pour sa configuration initiale et documentez les contrôles de l’assemblage révisé.','即使螺丝没有变化，更换衬套也可能改变孔径极限或有效轴向叠层。应将新孔径和叠层与成品肩轴的极限尺寸重新比较，再检查转动和落座情况。样品记录中同时注明衬套与螺丝版本。旧批准记录仍对应原配置，新装配需要做哪些检查则另行记录。');
put('automationNext','Konstruktionsstudie zum Automations-Drehgelenk','Ver el estudio de diseño del pivote de automatización','Seguire lo studio del perno per automazione','Consulter l’étude de conception du pivot d’automatisation','查看自动化转轴治具设计示例');

put('electronicsMetaTitle','Sonderschrauben für Elektronik und Optik','Tornillos a medida para electrónica y óptica','Viti su misura per elettronica e ottica','Vis sur mesure pour électronique et optique','电子与光学组件非标螺丝：空间、调节与接触');
put('electronicsMeta','Kompakte Schraubenköpfe, Feingewindeversteller und Exzenter für Elektronik und Optik spezifizieren, mit Prüfungen zu Zugang, Kontakt und Sauberkeit.','Defina cabezas compactas, ajustes de rosca fina e interfaces excéntricas para electrónica y óptica, con controles de acceso, contacto y limpieza.','Specificare teste compatte, regolazioni a passo fine ed eccentrici per elettronica e ottica, con controlli di accesso, contatto e pulizia.','Spécifiez têtes compactes, réglages à pas fin et interfaces excentriques pour électronique et optique, avec contrôles d’accès, de contact et de propreté.','为电子外壳和光学调节机构明确小型螺丝头、细牙及偏心接口，分别检查操作空间、接触状态和清洁要求。');
put('electronicsTitle','Zugang, Verstellung und Kontaktfläche prüfen','Revisar acceso, ajuste y superficie de contacto','Verificare accesso, regolazione e superficie di contatto','Examiner accès, réglage et surface de contact','分别评审操作空间、调节和接触表面');
put('electronicsIntro','Kompakte Gehäuse und optische Versteller brauchen unterschiedliche Schraubenschnittstellen. Die mechanische Aufgabe mit Nachbarteilen definieren; ein maßhaltiges Gewinde allein belegt keine optische Modulleistung.','Las carcasas compactas y los ajustes ópticos necesitan interfaces distintas. Defina la función mecánica con las piezas próximas; una rosca precisa no establece el rendimiento óptico del módulo.','Involucri compatti e regolazioni ottiche richiedono interfacce diverse. Definire il ruolo meccanico con i pezzi adiacenti: il solo filetto preciso non determina le prestazioni ottiche del modulo.','Boîtiers compacts et réglages optiques demandent des interfaces différentes. Définissez le rôle mécanique avec les pièces voisines ; un filetage précis ne suffit pas à établir les performances optiques du module.','小型外壳和光学调节机构需要不同的螺丝接口。应结合邻近零件明确机械作用；螺纹尺寸准确，并不代表模组的光学性能已得到验证。');
put('electronicsOne','Kompaktes Gehäuse schließen','Cerrar una carcasa compacta','Chiudere un involucro compatto','Fermer un boîtier compact','紧固小型外壳');
put('electronicsOneSpec','Kopfhöhe, Anlagefläche, Werkzeugansatz und verfügbare Gewindelochtiefe zeigen. Erscheinungsempfindliche Flächen benennen.','Indique altura de cabeza, asiento, acceso del destornillador y profundidad útil del agujero roscado. Identifique superficies sensibles a marcas.','Indicare altezza testa, appoggio, accesso dell’utensile e profondità disponibile nel foro filettato. Identificare superfici sensibili ai segni.','Indiquez hauteur de tête, face d’appui, accès du tournevis et profondeur disponible du taraudage. Repérez les surfaces d’aspect sensibles.','标出头高、落座面、批头进入方向和配合螺纹孔的可用深度，注明对外观敏感的表面。');
put('electronicsOneCheck','Prüfen, dass der Kopf anliegt, bevor das Schraubenende den Lochgrund berührt, und dass der vorgesehene Bit zugänglich ist. Zulässige Gehäusespuren dokumentieren.','Compruebe que el tornillo terminado asienta antes de tocar fondo y que entra la punta prevista. Registre las marcas permitidas en la carcasa.','Verificare che la vite finita vada in appoggio prima di toccare il fondo e che l’inserto previsto possa entrare. Registrare i segni ammessi sull’involucro.','Vérifiez que la vis finie prend appui avant de talonner et que l’embout prévu peut entrer. Consignez les marques admises sur le boîtier.','确认成品螺丝能先落座而不是先顶到孔底，且配套批头能够进入；记录外壳允许的接触痕迹。');
put('electronicsTwo','Feinverstellung übertragen','Transmitir un ajuste fino','Trasmettere una regolazione fine','Transmettre un réglage fin','通过细牙实现位移调节');
put('electronicsTwoSpec','Gewindesteigung, nutzbaren Hub, Kontaktendform und Halten der Einstellung festlegen. Gegenversteller und dessen Lagerung einbeziehen.','Defina paso, recorrido útil, extremo de contacto y retención del ajuste. Incluya el elemento regulado y su apoyo.','Specificare passo, corsa utile, forma dell’estremità e mantenimento della regolazione. Includere elemento accoppiato e supporto.','Spécifiez pas, course utile, forme d’extrémité et maintien du réglage. Incluez l’élément réglé et son support.','规定螺距、有效行程、接触端形状及调节位置的保持方式，并提供配合调节件和支撑结构。');
put('electronicsTwoCheck','Geforderte Bewegung und Rückkehr zur Referenzstellung erproben. Montageverstellung getrennt von Gewindemaßen prüfen.','Pruebe el movimiento requerido y el retorno a una referencia. Verifique el ajuste montado por separado de las dimensiones de rosca.','Provare il movimento richiesto e il ritorno alla posizione di riferimento. Verificare la regolazione montata separatamente dalle dimensioni del filetto.','Essayez le mouvement demandé et le retour à une position de référence. Vérifiez le réglage monté séparément des dimensions du filetage.','试验要求的运动及返回基准位置的情况，将整机调节功能与螺纹尺寸验收分开。');
put('electronicsThree','Mit einem Exzenter positionieren','Posicionar mediante una excéntrica','Posizionare con un eccentrico','Positionner avec un excentrique','利用偏心结构调整位置');
put('electronicsThreeSpec','Versatzrichtung und -betrag zu benannten Bezügen sowie Winkelreferenz und Kontaktbereich am Gegenstück angeben.','Indique dirección y magnitud del desplazamiento respecto a referencias identificadas, orientación angular y envolvente de contacto.','Indicare direzione ed entità dell’eccentricità rispetto a riferimenti definiti, riferimento angolare e ingombro di contatto.','Précisez direction et valeur du décalage par rapport aux références nommées, repère angulaire et enveloppe de contact.','按明确的基准规定偏心方向和偏心量，同时标明角度基准与配合接触范围。');
put('electronicsThreeCheck','Versatzgeometrie in der definierten Aufspannung prüfen und Verstellung im Modul erproben. Den Versatz nicht allein aus der Kopfkontur ableiten.','Compruebe la excentricidad en el montaje de medida definido y pruebe el ajuste en el módulo. No deduzca el desplazamiento solo del contorno de cabeza.','Controllare l’eccentricità nel piazzamento definito e provare la regolazione nel modulo. Non ricavare l’eccentricità dal solo profilo della testa.','Contrôlez le décalage dans le montage défini et essayez le réglage dans le module. Ne déduisez pas le décalage du seul contour de tête.','在规定的测量装夹下检查偏心几何，再放入模组试调，不能仅凭头部外形判断偏心量。');
put('electronicsCaseTitle','Änderungsbeispiel: eine Oberflächenbehandlung ergänzen','Ejemplo de cambio: añadir un acabado','Esempio di modifica: aggiungere una finitura','Exemple de modification : ajouter une finition','变更示例：增加表面处理');
put('electronicsCase','Festlegen, welche Maße nach Behandlung gelten, einschließlich Antriebsvertiefung, Feingewinde und Kontaktende. Den sauberen Montagezustand und vor Handhabungsschäden zu schützende Flächen definieren. Fertige Muster mit vorgesehenem Werkzeug und Gegenstücken vergleichen. Maßabnahme, Sauberkeit und gegebenenfalls optische Systemvalidierung brauchen getrennte Nachweise; sichtbare Sauberkeit belegt keinen gemessenen Partikelgrenzwert.','Revise qué dimensiones se aceptan después del acabado, incluidas huella, rosca fina y extremo. Defina limpieza antes del montaje y superficies que deben evitar daños por manipulación. Compare muestras terminadas con herramienta y piezas previstas. Aceptación dimensional, limpieza y validación óptica necesitan registros distintos; una pieza visualmente limpia no demuestra un límite de partículas medido.','Definire quali quote valgono dopo la finitura, comprese impronta, filetto fine ed estremità di contatto. Stabilire pulizia prima del montaggio e superfici da proteggere dalla manipolazione. Confrontare campioni finiti con utensile e pezzi previsti. Accettazione dimensionale, pulizia ed eventuale validazione ottica richiedono documenti distinti: una superficie visivamente pulita non dimostra un limite misurato di particelle.','Précisez les dimensions valables après finition, dont empreinte, filetage fin et extrémité de contact. Définissez la propreté avant montage et les surfaces à protéger des dommages de manipulation. Comparez les échantillons finis à l’outil et aux pièces prévus. Réception dimensionnelle, propreté et éventuelle validation optique exigent des documents distincts ; un aspect propre ne prouve pas une limite de particules mesurée.','应明确哪些尺寸按表面处理后的状态验收，包括批头槽、细牙和接触端。规定装配前所需的清洁状态，以及搬运中应避免损伤的表面。用配套工具和实际配合件检查成品样件。尺寸验收、清洁度和必要的光学系统验证应分别记录；目视干净不能证明满足某个实测颗粒限值。');
put('electronicsNext','Exzenterbezüge und Verstellgeometrie prüfen','Revisar referencias y geometría de ajuste excéntrico','Valutare riferimenti ed eccentricità di regolazione','Examiner références et géométrie du réglage excentrique','查看偏心基准与调节几何说明');

put('energyMetaTitle','Sonderbefestiger für Lade- und Energieanlagen','Fijaciones para equipos de recarga y energía','Fissaggi per apparecchiature di ricarica ed energia','Fixations pour équipements de recharge et d’énergie','充电与储能设备非标螺丝：外壳、孔道与连接');
put('energyMeta','Wartungsdeckel, Kabeldurchführungen und leitende Verbindungen in Lade- und Speicheranlagen unterscheiden. Kontakt, Oberfläche und Montageabnahme definieren.','Separe tornillos de tapas de servicio, pasos de cable y conexiones conductoras en recarga y almacenamiento. Defina contacto, acabado y aceptación del conjunto.','Distinguere viti per coperchi di servizio, passaggi cavo e collegamenti conduttivi in ricarica e accumulo. Definire contatto, finitura e accettazione.','Distinguez vis de panneaux de service, passages de câbles et connexions conductrices dans la recharge et le stockage. Définissez contact, finition et réception.','区分充电及储能设备的维护面板螺丝、线缆孔道与导电连接，分别明确接触材料、表面状态和装配验收。');
put('energyTitle','Gehäuse-, Durchführungs- und Kontaktaufgaben trennen','Separar carcasa, paso y contacto eléctrico','Distinguere involucro, passaggio e contatto elettrico','Distinguer boîtier, passage et contact électrique','把外壳、孔道与电接触分开评审');
put('energyIntro','Eine Wartungsplattenschraube hat andere Anforderungen als eine Kabeldurchführung oder leitende Verbindung. Die tatsächliche Schnittstelle bestimmen, bevor Werkstoff und Oberfläche gewählt werden.','El tornillo que cierra un panel de servicio no tiene la misma especificación que un paso de cable o una conexión conductora. Identifique la interfaz antes de elegir material y acabado.','La vite di un pannello di servizio non ha la stessa specifica di un passaggio cavo o di un collegamento conduttivo. Identificare l’interfaccia prima di scegliere materiale e finitura.','La vis qui ferme un panneau de service ne relève pas de la même spécification qu’un passage de câble ou une connexion conductrice. Identifiez l’interface avant de choisir matière et finition.','关闭维护面板的螺丝，与线缆通道或导电连接件，需要的规格并不相同。选材料和表面处理前，应先确认实际承担的接口功能。');
put('energyOne','Wartungsdeckel halten','Retener una tapa de servicio','Trattenere un coperchio di servizio','Retenir un panneau de service','保持可维护面板');
put('energyOneSpec','Deckeldicke, Werkzeugzugang, Halteanordnung und Umgebung festlegen. Gelöste und angezogene Position benennen.','Defina espesor de tapa, acceso, retención y exposición. Identifique tanto posición liberada como apretada.','Definire spessore coperchio, accesso utensile, ritegno ed esposizione. Identificare posizione allentata e serrata.','Définissez épaisseur, accès de l’outil, retenue et exposition. Repérez les positions desserrée et serrée.','明确盖板厚度、工具进入空间、防脱结构及使用环境，同时标明松开与锁紧位置。');
put('energyOneCheck','Öffnen, Halten und Wiedereingriff mit dem Wartungswerkzeug prüfen. Beschichtung und erforderliche Gehäuseprüfungen für die komplette Baugruppe vereinbaren.','Revise apertura, retención y reacoplamiento con la herramienta de servicio. Acuerde recubrimiento y controles del cerramiento completo.','Verificare apertura, ritenzione e riavvitamento con l’utensile di servizio. Concordare rivestimento ed eventuali controlli dell’involucro completo.','Examinez ouverture, retenue et réengagement avec l’outil de service. Convenez du revêtement et des contrôles du boîtier complet.','使用维修工具检查打开、防脱保持和重新旋合，针对完整外壳约定涂层及所需的整机检查。');
put('energyTwo','Kabel durch ein Bauteil führen','Pasar un cable por una pieza','Far passare un cavo nel componente','Faire passer un câble dans une pièce','让线缆穿过零件');
put('energyTwoSpec','Kabelhüllraum, Bohrungsverlauf, Eintrittskanten und benachbarte Hindernisse zeigen. Mechanischen Freiraum von Isolationsanforderungen unterscheiden.','Muestre envolvente del cable, recorrido del taladro, bordes de entrada y restricciones próximas. Distinga holgura mecánica y aislamiento.','Indicare ingombro del cavo, percorso del foro, bordi d’ingresso e vincoli vicini. Distinguere spazio meccanico e requisiti d’isolamento.','Indiquez enveloppe du câble, trajet du perçage, arêtes d’entrée et contraintes voisines. Distinguez dégagement mécanique et isolation.','提供线缆外形范围、孔道路线、入口边缘和邻近限制条件，将机械净空与绝缘要求分开。');
put('energyTwoCheck','Kanal und Innenkanten vor Verlust des Zugangs prüfen. Vorgesehene Führung erproben; der Bohrungsdurchmesser allein belegt keinen Kabelschutz.','Inspeccione paso y bordes internos antes de perder acceso. Pruebe el trazado previsto; el diámetro del taladro no demuestra protección del cable.','Controllare passaggio e bordi interni prima di perdere l’accesso. Provare l’instradamento previsto: il diametro del foro non dimostra la protezione del cavo.','Contrôlez passage et arêtes internes avant de perdre l’accès. Essayez le cheminement prévu ; le diamètre du perçage ne suffit pas à établir la protection du câble.','趁内部仍可接近时检查孔道和边缘，并试走实际线路；仅有孔径合格不能证明线缆受到保护。');
put('energyThree','Leitende Verbindung klemmen','Apretar una conexión conductora','Serrare un collegamento conduttivo','Serrer une connexion conductrice','夹紧导电连接');
put('energyThreeSpec','Strompfad, Kontaktwerkstoffe, Oberfläche und Klemmstapel benennen. Festlegen, ob das Gewindeteil leitet oder nur klemmt.','Identifique trayectoria de corriente, materiales de contacto, acabado y cadena apretada. Indique si la pieza roscada conduce o solo aprieta.','Identificare percorso della corrente, materiali di contatto, finitura e pacco serrato. Specificare se il componente filettato conduce o fornisce solo serraggio.','Identifiez trajet du courant, matériaux de contact, finition et empilage serré. Précisez si la pièce filetée conduit ou fournit seulement le serrage.','注明电流路径、接触材料、表面状态和夹紧叠层，并说明螺纹件本身导电，还是仅提供夹紧力。');
put('energyThreeCheck','Montagebedingungen sowie erforderliche elektrische und thermische Abnahme der Verbindung vereinbaren. Werkstoffleitfähigkeit allein ist keine Anschlussbemessung.','Acuerde condiciones de montaje y aceptación eléctrica y térmica de la unión. La conductividad del material no establece la capacidad de la conexión.','Concordare condizioni di montaggio e accettazione elettrica e termica del giunto. La conducibilità del materiale non definisce la portata del collegamento.','Convenez du montage et de la réception électrique et thermique du joint. La conductivité de la matière ne constitue pas une valeur assignée de connexion.','约定装配条件及连接的电气、温升等验收要求。材料导电率不能直接当作连接的额定能力。');
put('energyCaseTitle','Änderungsbeispiel: beschichtetes Verbindungsteil ersetzen','Ejemplo de cambio: sustituir una pieza de conexión recubierta','Esempio di modifica: sostituire un componente di collegamento rivestito','Exemple de modification : remplacer une pièce de connexion revêtue','变更示例：替换带镀层的连接件');
put('energyCase','Vorgeschlagenen Grundwerkstoff, Beschichtung und Kontaktflächen mit der freigegebenen Verbindung vergleichen. Änderungen an Anlage, Gewindepassung und Montageverfahren bestimmen, bevor wiederholte Verbindungsprüfungen festgelegt werden. Kontaktstapel und Versionsinformationen im Nachweis erhalten. Ein Werkstoffzeugnis der Schraube ersetzt weder elektrische Verbindungsprüfungen noch die Gerätefreigabe.','Compare material base, recubrimiento y superficies propuestos con la unión aprobada. Identifique cambios en asiento, ajuste de rosca y montaje antes de decidir qué controles repetir. Conserve la cadena de contacto y sus revisiones en el registro. Un certificado de material del tornillo no sustituye ensayos de conexión eléctrica ni aprobación del equipo.','Confrontare materiale base, rivestimento e contatti proposti con il giunto approvato. Identificare modifiche ad appoggio, accoppiamento del filetto e montaggio prima di stabilire i controlli da ripetere. Conservare dati della pila di contatto e revisioni. Un certificato del materiale della vite non sostituisce prove del collegamento elettrico o approvazione dell’apparecchiatura.','Comparez matière de base, revêtement et surfaces proposés à la connexion approuvée. Repérez les modifications d’appui, d’ajustement du filetage et de montage avant de choisir les contrôles à répéter. Conservez empilage de contact et indices dans le dossier. Un certificat matière de vis ne remplace ni les essais de connexion électrique ni l’approbation de l’équipement.','把拟替换件的基材、镀层和接触面与已批准连接逐项比较，先找出落座、螺纹配合及装配步骤的变化，再决定重复哪些连接检查。记录中保留接触叠层和版本信息。螺丝的材料证明不能代替电连接试验或设备批准。');
put('energyNext','Schnittstellen von Ladegehäusen näher betrachten','Leer sobre interfaces de cerramientos de recarga','Leggere le interfacce degli involucri di ricarica','Lire l’analyse des interfaces de boîtiers de recharge','阅读充电设备外壳接口分析');

put('fluidMetaTitle','Hohlschrauben und Befestiger für Fluidanlagen','Tornillos huecos y fijaciones para equipos de fluidos','Viti cave e fissaggi per apparecchiature fluidiche','Vis creuses et fixations pour équipements de fluides','流体设备中空螺丝：固定、通流与密封');
put('fluidMeta','Halten, Durchfluss und Abdichten getrennt prüfen. Bohrungsgeometrie, Medium, Dichtschnittstelle, Sauberkeit und vereinbarte Funktionsprüfungen spezifizieren.','Revise por separado retención, paso de fluido y sellado. Defina taladro, medio, interfaz de sellado, limpieza y ensayos funcionales acordados.','Valutare separatamente ritegno, passaggio e tenuta. Specificare foro, fluido, interfaccia di tenuta, pulizia e prove funzionali concordate.','Examinez séparément maintien, passage et étanchéité. Spécifiez perçage, fluide, interface d’étanchéité, propreté et essais fonctionnels convenus.','将流体设备中的固定、通流与密封功能分别评审，明确孔道、介质、密封接口、清洁及约定功能试验。');
put('fluidTitle','Halten, Durchfluss und Abdichten unterscheiden','Distinguir retención, paso y sellado','Distinguere ritegno, passaggio e tenuta','Distinguer maintien, passage et étanchéité','分别定义固定、通流与密封');
put('fluidIntro','Eine Hohlschraube kann einen Kanal bilden, ohne selbst das Dichtelement zu sein. Zeigen Sie Mediumspfad, Dichtstelle und das haltende Merkmal der Baugruppe.','Un tornillo hueco puede crear un paso sin ser el elemento sellante. Muestre por dónde circula el medio, dónde sella y qué retiene el conjunto.','Una vite cava può fornire un passaggio senza essere l’elemento di tenuta. Indicare percorso del fluido, sede della tenuta e caratteristica che trattiene l’assieme.','Une vis creuse peut offrir un passage sans constituer l’élément d’étanchéité. Montrez trajet du fluide, emplacement du joint et fonction de maintien.','中空螺丝可以提供流道，但未必是密封元件。图纸应标明介质从哪里流过、密封作用在哪里，以及哪个结构负责保持装配。');
put('fluidOne','Deckel oder Bauteil halten','Retener una tapa o componente','Trattenere un coperchio o componente','Maintenir un couvercle ou composant','固定盖板或组件');
put('fluidOneSpec','Auflagefläche, Klemmstapel, Gegengewinde und Lastfall festlegen. Separate Dichtung im Zusammenbau benennen.','Defina apoyo, cadena apretada, rosca acoplada y carga. Identifique cualquier junta independiente en el conjunto.','Definire appoggio, pacco serrato, filetto accoppiato e carico. Identificare eventuali guarnizioni separate nell’assieme.','Définissez face d’appui, empilage serré, taraudage en regard et cas de charge. Repérez tout joint séparé dans l’assemblage.','规定承压面、夹紧叠层、配合螺纹及载荷情况，并注明装配中的独立密封件或垫片。');
put('fluidOneCheck','Anlage und nutzbaren Gewindeeingriff prüfen. Verbindungsabnahme unabhängig vom sichtbaren Schraubenprofil festlegen.','Compruebe asiento y acoplamiento útil. Defina la aceptación de la unión con independencia del perfil visible del tornillo.','Controllare appoggio e impegno utile del filetto. Definire l’accettazione del giunto indipendentemente dal profilo visibile.','Vérifiez appui et engagement utile. Définissez la réception du joint indépendamment du profil visible de la fixation.','检查落座和有效旋合长度，单独规定连接验收，不能只根据螺丝外形判断。');
put('fluidTwo','Innenkanal bereitstellen','Proporcionar un paso interno','Fornire un passaggio interno','Créer un passage interne','提供内部流道');
put('fluidTwoSpec','Gesamte Bohrung, Querbohrungen, Restwand, Innenkanten und Reinigungszugang zeigen. Medium und geforderte Durchflussfunktion angeben.','Muestre taladro completo, cruces, pared restante, bordes internos y acceso de limpieza. Indique medio y función de caudal requerida.','Indicare foro completo, fori trasversali, parete residua, bordi interni e accesso alla pulizia. Specificare fluido e funzione di portata richiesta.','Montrez perçage complet, trous transversaux, paroi résiduelle, arêtes internes et accès au nettoyage. Précisez fluide et fonction de débit.','标出完整内孔、横向孔、剩余壁厚、内部边缘及清洗空间，说明介质和要求的通流功能。');
put('fluidTwoCheck','Verdeckte Verschneidungen in geeigneter Fertigungsstufe prüfen. Erforderliche Durchfluss- und Sauberkeitsprüfungen zum festgelegten Kanal vereinbaren.','Inspeccione intersecciones ocultas en una fase adecuada. Acuerde ensayos de caudal y limpieza para el paso especificado.','Controllare intersezioni nascoste nella fase opportuna. Concordare eventuali prove di portata e pulizia sul passaggio specificato.','Contrôlez les intersections cachées à une étape appropriée. Convenez des essais de débit et de propreté du passage spécifié.','在合适工序检查隐藏的相贯处，针对规定孔道约定所需的流量及清洁检查。');
put('fluidThree','Teil einer Dichtverbindung sein','Formar parte de una unión estanca','Partecipare a un giunto di tenuta','Participer à un assemblage étanche','参与密封连接');
put('fluidThreeSpec','Dichtungsart, Gegensitz, Kontaktoberfläche und Montagezustand benennen. Medium, Temperatur und Druckbedingungen der Anwendung angeben.','Identifique tipo de sello, asiento acoplado, acabado de contacto y montaje. Indique medio, temperatura y presión de uso.','Identificare tipo di tenuta, sede accoppiata, finitura di contatto e montaggio. Specificare fluido, temperatura e pressione d’impiego.','Identifiez type de joint, siège en regard, finition de contact et montage. Précisez fluide, température et pression d’utilisation.','明确密封类型、配合座面、接触表面和装配状态，并说明实际介质、温度与压力条件。');
put('fluidThreeCheck','Aufbau, Dauer, Messung und Annahmekriterien der festgelegten Leck- oder Druckprüfung definieren. Die Prüfung einer offenen Bohrung ist etwas anderes.','Defina montaje de ensayo, duración, medida y criterios para las pruebas de fuga o presión especificadas. Inspeccionar un taladro abierto es otro control.','Definire allestimento, durata, misura e criteri delle prove di perdita o pressione prescritte. Il controllo del foro aperto è una verifica diversa.','Définissez montage, durée, mesure et critères des essais de fuite ou de pression spécifiés. L’examen d’un perçage ouvert est un contrôle différent.','针对要求的泄漏或压力试验，明确装夹、持续时间、测量方法和合格标准。检查开口孔道属于另一项检查。');
put('fluidCaseTitle','Änderungsbeispiel: einen radialen Kanal ergänzen','Ejemplo de cambio: añadir un paso radial','Esempio di modifica: aggiungere un passaggio radiale','Exemple de modification : ajouter un passage radial','变更示例：增加径向通道');
put('fluidCase','Eine neue Querbohrung verändert den örtlichen Querschnitt und die nachzubearbeitende Innenkante. Prüfen Sie die Verschneidung vor Festlegung von Entgraten und Reinigung. Vereinbaren Sie eine Prüfung des verdeckten Bereichs, solange er zugänglich bleibt, und bewahren Sie Fertigmaße und geforderte Funktionsprüfnachweise auf. Weder Produktname noch erfolgreiche Maßprüfung ergeben eine Druckfreigabe.','Un nuevo taladro transversal cambia la sección local y el borde interno que debe acabarse. Revise el cruce antes de fijar desbarbado y limpieza. Acuerde cómo inspeccionar la zona oculta mientras sea accesible y conserve dimensiones finales y registros funcionales exigidos. Ni el nombre del producto ni una inspección dimensional correcta establecen capacidad de presión.','Un nuovo foro trasversale modifica sezione locale e bordo interno da rifinire. Valutare l’intersezione prima di definire sbavatura e pulizia. Concordare il controllo dell’area nascosta finché accessibile, poi conservare quote finite e prove funzionali richieste. Nome del prodotto e controllo dimensionale superato non determinano una capacità di pressione.','Un trou transversal ajouté modifie la section locale et l’arête interne à finir. Examinez l’intersection avant de définir ébavurage et nettoyage. Convenez du contrôle de la zone cachée tant qu’elle reste accessible, puis conservez dimensions finies et essais fonctionnels prescrits. Ni le nom du produit ni un contrôle dimensionnel réussi n’établissent une capacité en pression.','新增横向孔会同时改变局部截面和需要处理的内部边缘。确定去毛刺、清洗顺序前，先评审相贯处；约定在内部仍可接近时如何检查，再保留最终尺寸及规定的功能试验记录。产品名称或外形尺寸筛选合格都不能直接说明承压能力。');
put('fluidNext','Bohrungsgeometrie und Innenkantenabnahme festlegen','Definir geometría del taladro y aceptación de bordes internos','Definire geometria del foro e accettazione dei bordi interni','Définir géométrie du perçage et réception des arêtes internes','明确孔道几何与内部边缘验收');

put('toolingMetaTitle','Sonderschrauben für Formen, Werkzeuge und Prüfvorrichtungen','Tornillos a medida para moldes, utillajes y pruebas','Viti su misura per stampi, attrezzature e collaudo','Vis sur mesure pour moules, outillages et bancs d’essai','模具与测试治具非标螺丝：定位、止挡与夹紧');
put('toolingMeta','Positionierstufen, verstellbare Anschläge und Nutspannungen spezifizieren. Kontaktverschleiß, Ersatzteile und Einrichtnachweise für Werkzeuge und Prüfvorrichtungen prüfen.','Defina escalones de posición, topes regulables y fijaciones en ranura. Revise desgaste, repuestos y registros de puesta a punto del utillaje.','Specificare gradini di posizionamento, arresti regolabili e serraggi in cava. Valutare usura, ricambi e documenti di messa a punto.','Spécifiez épaulements de positionnement, butées réglables et bridages en rainure. Examinez usure de contact, pièces de rechange et réglages.','为模具、工装及测试治具明确定位台阶、可调止挡和槽内夹紧要求，检查接触磨损、替换件与工装设定记录。');
put('toolingTitle','Positionieren, Anschlagen und Spannen getrennt festlegen','Distinguir posicionamiento, tope y apriete','Distinguere posizionamento, arresto e serraggio','Distinguer positionnement, butée et bridage','把定位、止挡与夹紧要求分开');
put('toolingIntro','Eine Vorrichtung braucht einen definierten Werkstückbezug und ausreichend Freiraum zum Be- und Entladen. Zeigen Sie, welche Schraubenfläche den Bezug bestimmt, welcher Kontakt verschleißen kann und welches Merkmal nur spannt.','Un útil necesita una referencia de pieza definida y espacio para cargar y retirar la pieza. Indique qué superficie del tornillo fija la referencia, qué contacto puede desgastarse y qué elemento solo aprieta.','Un’attrezzatura richiede un riferimento del pezzo definito e spazio per caricarlo e rimuoverlo. Indicare quale superficie della vite stabilisce il riferimento, quale contatto può usurarsi e quale elemento serra soltanto.','Un montage exige une référence pièce définie et du dégagement pour charger et retirer la pièce. Montrez quelle surface de vis fixe la référence, quel contact peut s’user et quel élément assure seulement le bridage.','治具既要有明确的工件定位基准，也要留出装入和取出的空间。图纸应说明哪个螺丝表面决定基准、哪个接触部位可能磨损，以及哪个结构只负责夹紧。');
put('toolingOne','Abnehmbares Vorrichtungselement positionieren','Posicionar un elemento desmontable del útil','Posizionare un elemento rimovibile dell’attrezzatura','Positionner un élément démontable du montage','定位可拆卸治具组件');
put('toolingOneSpec','Funktionale Stufe oder Schulter, Gegenbohrung und Anlagefläche benennen. Funktionsstufen von den vereinbarten Bezügen bemaßen, statt unabhängige Längen aufzusummieren.','Identifique escalón u hombro funcional, orificio acoplado y asiento. Acote desde las referencias acordadas en lugar de acumular longitudes independientes.','Identificare gradino o spallamento funzionale, foro accoppiato e appoggio. Quotare i gradini dai riferimenti concordati anziché sommare lunghezze indipendenti.','Identifiez gradin ou épaulement fonctionnel, alésage et face d’appui. Cotez depuis les références convenues plutôt que de cumuler des longueurs indépendantes.','明确起作用的台阶或肩轴、配合孔和落座面。功能台阶应从约定基准标注，避免把互不相关的长度逐段累加。');
put('toolingOneCheck','Fertige Positionierflächen und Gegenpassung prüfen. Aus- und Wiedereinbau anhand der festgelegten Bezugsposition erproben.','Compruebe superficies de posición terminadas y ajuste acoplado. Pruebe desmontaje y remontaje respecto a la posición de referencia especificada.','Controllare superfici finite di posizionamento e accoppiamento. Provare rimozione e rimontaggio rispetto alla posizione di riferimento.','Contrôlez les surfaces de positionnement finies et l’ajustement. Essayez dépose et repose par rapport à la position de référence.','检查成品定位面与配合状态，并按规定基准位置试验拆卸和重新安装。');
put('toolingTwo','Verstellbaren Werkstückanschlag einstellen','Ajustar un tope regulable de pieza','Regolare un arresto del pezzo','Régler une butée de pièce','设定可调工件止挡');
put('toolingTwoSpec','Kontaktspitze oder Auflage, Verstellweg, Sicherung und zulässige Werkstückspuren definieren. Austauschbare Kontaktelemente benennen.','Defina punta o apoyo, recorrido, bloqueo y marcas permitidas en la pieza. Identifique elementos de contacto sustituibles.','Definire punta o pattino, corsa, bloccaggio e segni ammessi sul pezzo. Identificare gli elementi di contatto sostituibili.','Définissez pointe ou patin, course, blocage et marques admises sur la pièce. Repérez les éléments de contact remplaçables.','规定接触端或垫块、调节行程、锁定方式及工件允许的压痕，并注明可替换的接触件。');
put('toolingTwoCheck','Anschlagposition und Kontaktzustand vor und nach dem vereinbarten Verstellablauf dokumentieren. Positionswiederholbarkeit getrennt vom sichtbaren Verschleiß bewerten.','Registre posición del tope y contacto antes y después de la secuencia acordada. Compare repetibilidad de posición por separado del desgaste visible.','Registrare posizione e contatto prima e dopo la sequenza concordata. Valutare ripetibilità della posizione separatamente dall’usura visibile.','Consignez position et contact avant et après la séquence convenue. Comparez répétabilité de position et usure visible séparément.','记录约定调节过程前后的止挡位置和接触状态，将位置重复性与可见磨损分开判断。');
put('toolingThree','Durch Maschinen- oder Vorrichtungsnut spannen','Apretar mediante una ranura de máquina o útil','Serrare attraverso una cava della macchina o attrezzatura','Brider dans une rainure de machine ou de montage','通过机台或治具槽夹紧');
put('toolingThreeSpec','Tatsächlichen Nutquerschnitt, Kopftasche, Einführweg und Auflagebereich zeigen. Gewindeeingriff und Klemmstapel festlegen.','Muestre sección real de ranura, alojamiento de cabeza, inserción y apoyo. Defina rosca acoplada y cadena a apretar.','Indicare sezione reale della cava, sede testa, percorso d’inserimento e appoggio. Definire impegno del filetto e pacco serrato.','Montrez section réelle de rainure, logement de tête, trajet d’insertion et appui. Définissez engagement et empilage serré.','提供真实槽截面、头部容纳空间、装入路径和承压范围，规定有效旋合及被夹紧的叠层。');
put('toolingThreeCheck','Einführen, Kopfanlage und Verdrehsicherung in der vorgesehenen Nut prüfen. Der Kopf muss an der festgelegten Fläche anliegen, ohne anderswo vorzeitig aufzusetzen.','Compruebe inserción, asiento y antigiro en la ranura prevista. Confirme apoyo en la cara indicada sin tocar fondo en otra zona.','Verificare inserimento, appoggio testa e antirotazione nella cava prevista. Accertare l’appoggio sulla faccia specificata senza interferenze altrove.','Vérifiez insertion, appui de tête et antirotation dans la rainure prévue. Confirmez l’appui sur la face spécifiée sans talonnage ailleurs.','在实际槽内检查能否装入、头部落座和防转，确认头部压在规定承压面上，而非先在其他位置顶住。');
put('toolingCaseTitle','Änderungsbeispiel: verschlissene Kontaktauflage ersetzen','Ejemplo de cambio: sustituir un apoyo desgastado','Esempio di modifica: sostituire un pattino usurato','Exemple de modification : remplacer un patin usé','变更示例：更换磨损的接触垫块');
put('toolingCase','Dicke, Kontaktform und Werkstoffzustand der Ersatzauflage mit der freigegebenen Einrichtung vergleichen. Eine neue Auflage kann den Werkstückbezug verschieben, obwohl die Schraubeneinstellung unverändert bleibt. Bezug neu einstellen, Verstellgrenzen prüfen und Auflagen- sowie Schraubenstand dokumentieren. Einrichtmessungen von späteren Werkstückprüfungen trennen, damit die erfolgreiche Vorrichtungsprüfung nicht als Produktabnahme gilt.','Compare espesor, forma y estado del material del apoyo nuevo con la puesta a punto aprobada. Puede cambiar la referencia de la pieza aunque el tornillo conserve su ajuste. Restablezca la referencia, revise límites de ajuste y registre revisiones de apoyo y tornillo. Separe medidas de puesta a punto de la inspección posterior de piezas para no confundir aceptación del útil y del producto.','Confrontare spessore, forma e stato del materiale del pattino sostitutivo con la configurazione approvata. Il nuovo pattino può spostare il riferimento del pezzo anche senza modificare la vite. Ripristinare il riferimento, controllare limiti e registrare revisioni di pattino e vite. Separare misure di messa a punto e controlli successivi del pezzo: una verifica positiva dell’attrezzatura non è accettazione del prodotto.','Comparez épaisseur, forme et état matière du patin neuf au réglage approuvé. Le patin peut déplacer la référence pièce sans changement de vis. Rétablissez la référence, vérifiez les limites de réglage et consignez indices du patin et de la vis. Séparez mesures de réglage et contrôles ultérieurs des pièces afin de distinguer validation du montage et réception du produit.','将替换垫块的厚度、接触形状和材料状态与已批准的工装设定比较。即便螺丝位置没动，新垫块也可能改变工件基准。应重新建立基准位置、检查调节极限，并记录垫块与螺丝版本。工装设定测量与后续工件检查分别记录，不能把治具检查通过直接当作产品验收。');
put('toolingNext','Gewindestiftspitzen und Kontaktspuren vergleichen','Comparar puntas de prisionero y marcas de contacto','Confrontare punte dei grani e segni di contatto','Comparer pointes de vis de pression et marques de contact','比较紧定螺丝端型与接触压痕');

put('securityMetaTitle','Sicherheitsschrauben für Schutz- und Zugangsgehäuse','Tornillos antimanipulación para equipos de seguridad y acceso','Viti antimanomissione per apparecchiature di sicurezza e accesso','Vis inviolables pour équipements de sécurité et d’accès','安防与门禁设备防拆螺丝：槽型、保持与维护');
put('securityMeta','Spezialantriebe, unverlierbare Wartungsplatten und versenkte Auflagen prüfen. Werkzeug, Zugangsweg und fertige Baugruppe aufeinander abstimmen.','Revise huellas especiales, paneles de servicio imperdibles y apoyos rebajados. Coordine herramienta, acceso y conjunto terminado.','Valutare impronte speciali, pannelli di servizio con viti imperdibili e appoggi incassati. Coordinare utensile, accesso e assieme finito.','Examinez empreintes spéciales, panneaux de service à vis imperdables et appuis encastrés. Coordonnez outil, accès et assemblage fini.','评审安防外壳的防拆槽型、防脱维护面板和沉台承压面，将配套工具、操作空间及成品装配一起确认。');
put('securityTitle','Erschwerten Zugang und autorisierte Wartung gemeinsam auslegen','Diseñar para acceso restringido y mantenimiento autorizado','Progettare accesso limitato e manutenzione autorizzata','Prévoir accès restreint et maintenance autorisée','兼顾限制拆卸与授权维护');
put('securityIntro','Ein Spezialantrieb kann beiläufiges Entfernen erschweren und geplante Wartung erlauben. Passendes Werkzeug und Zugang im Einbau festlegen, dann entscheiden, ob die gelöste Schraube an der Platte verbleiben muss.','Una huella especial puede disuadir la retirada casual y permitir el servicio previsto. Defina herramienta y acceso instalados y decida si el tornillo liberado debe quedar unido al panel.','Un’impronta speciale può scoraggiare rimozioni occasionali consentendo la manutenzione prevista. Specificare utensile e accesso montato, poi decidere se la vite allentata debba restare sul pannello.','Une empreinte spéciale peut décourager un démontage occasionnel tout en permettant l’entretien prévu. Définissez outil et accès en place, puis décidez si la vis desserrée doit rester sur le panneau.','特殊槽型可以增加随意拆卸的难度，同时保留计划内维护的可能。先明确配套工具和装机后的操作空间，再决定松开后的螺丝是否必须留在面板上。');
put('securityOne','Antriebsschnittstelle einschränken','Restringir la interfaz de accionamiento','Limitare l’interfaccia di azionamento','Restreindre l’interface d’entraînement','规定受限的驱动接口');
put('securityOneSpec','Vertiefungsprofil, nutzbaren Eingriff und gegebenenfalls Mittelstift benennen. Bit und Halter zusammen mit der fertigen Kopfgeometrie spezifizieren.','Identifique perfil, acoplamiento útil y tetón central si existe. Especifique punta y portapuntas con la geometría final de cabeza.','Identificare profilo, impegno utile ed eventuale perno centrale. Specificare inserto e portainserto con la geometria finita della testa.','Identifiez profil, engagement utile et éventuel téton central. Spécifiez embout et porte-embout avec la géométrie finie de tête.','明确槽型轮廓、有效啮合及适用的中柱要求，将批头、夹持器和成品头部几何一起规定。');
put('securityOneCheck','Fertige Vertiefung mit dem benannten Werkzeug zunächst außerhalb des Gehäuses, dann im Einbau vergleichen. Werkzeugpassung und Zugangshindernis unterscheiden.','Compare la huella terminada con la herramienta identificada fuera de la carcasa y luego instalada. Distinga ajuste de herramienta y restricción de acceso.','Confrontare impronta finita e utensile identificato prima fuori dall’involucro, poi in posizione montata. Distinguere accoppiamento e accessibilità.','Comparez empreinte finie et outil identifié hors du boîtier, puis en place. Distinguez ajustement de l’outil et restriction d’accès.','先在外壳外比较成品槽型与指定工具，再装机检查，区分批头不匹配与操作空间受阻。');
put('securityTwo','Befestiger bei der Plattenwartung zurückhalten','Retener los elementos al mantener el panel','Trattenere la viteria durante la manutenzione del pannello','Retenir les fixations pendant l’entretien du panneau','维护面板时保留螺丝');
put('securityTwoSpec','Plattendicke, Haltemerkmal, gelösten Hub und Gegengewinde zeigen. Öffnungsweg und benachbarte Kabel oder Bauteile benennen.','Muestre espesor, retención, recorrido liberado y rosca acoplada. Identifique apertura y cables o componentes próximos.','Indicare spessore, ritegno, corsa libera e filetto accoppiato. Identificare apertura e cavi o componenti adiacenti.','Montrez épaisseur, retenue, course desserrée et taraudage en regard. Repérez trajet d’ouverture et câbles ou composants voisins.','标出板厚、防脱结构、松开行程和配合螺纹，注明面板打开路径及邻近线缆或组件。');
put('securityTwoCheck','Rückhaltung nach Gewindelösung, Öffnungsfreigang und Wiedereingriff mit Wartungswerkzeug prüfen. Freigegebene Platten- und Haltekonfiguration dokumentieren.','Compruebe retención tras soltar la rosca, espacio de apertura y reacoplamiento con la herramienta de servicio. Registre panel y retenedor aprobados.','Controllare ritenzione dopo disimpegno, spazio d’apertura e riavvitamento con l’utensile di servizio. Registrare configurazione approvata di pannello e ritegno.','Vérifiez retenue après désengagement, dégagement d’ouverture et réengagement avec l’outil de service. Consignez panneau et retenue approuvés.','检查脱开螺纹后的保持、打开净空及使用维修工具重新旋合，并记录批准的面板与保持件组合。');
put('securityThree','Kopf in einer Schutzvertiefung auflegen','Asentar una cabeza en un rebaje protector','Alloggiare una testa in un incasso protettivo','Asseoir une tête dans un logement protecteur','让头部在防护沉台内落座');
put('securityThreeSpec','Vertiefungstiefe, Seitenfreigang, Auflagefläche und Beschichtung oder Dichtung im Stapel angeben. Zulässige sichtbare Kontaktspuren festlegen.','Indique profundidad, holgura lateral, apoyo y recubrimiento o junta en la cadena. Defina marcas visibles admisibles.','Indicare profondità, spazio laterale, appoggio ed eventuali rivestimenti o guarnizioni nel pacco. Definire segni visibili ammessi.','Indiquez profondeur, jeu latéral, appui et éventuel revêtement ou joint dans l’empilage. Définissez les marques visibles admises.','提供沉台深度、侧壁净空、承压面，以及叠层中的涂层或密封件，规定允许的可见接触痕迹。');
put('securityThreeCheck','Anlage und Werkzeugzugang an fertigen Gegenstücken bestätigen. Geforderte Gehäuseleistung an der kompletten Baugruppe getrennt von Schraubenmaßen prüfen.','Confirme asiento y acceso en piezas terminadas. Verifique el rendimiento de cerramiento exigido en el conjunto completo, aparte de las dimensiones del tornillo.','Confermare appoggio e accesso sui pezzi finiti. Verificare le prestazioni richieste dell’involucro completo separatamente dalle quote della vite.','Confirmez appui et accès sur pièces finies. Vérifiez les performances de boîtier prescrites sur l’assemblage complet, séparément des dimensions de vis.','在成品配合件上确认落座和工具空间。规定的外壳性能应在完整装配上验证，与螺丝尺寸检查分开。');
put('securityCaseTitle','Änderungsbeispiel: anderen Wartungsbit oder Halter einsetzen','Ejemplo de cambio: usar otra punta o portapuntas de servicio','Esempio di modifica: cambiare inserto o portainserto di servizio','Exemple de modification : changer l’embout ou son porte-embout','变更示例：更换维修批头或夹持器');
put('securityCase','Beim Ersatzvergleich Schraubenzeichnung, Vertiefungsreferenz und ursprüngliche Werkzeugkennung bereithalten. Vor Freigabe nutzbaren Eingriff und Halterhüllraum im tatsächlichen Gehäuse prüfen. Den Werkzeugstand mit Schrauben- und Plattenkonfiguration dokumentieren, einschließlich Ersatzspezifikation. Die Spezialantriebsgeometrie ist weder unabhängig zertifizierte Sicherheitsstufe noch Gehäuseschutzart.','Conserve plano, referencia de huella e identidad de herramienta original al comparar un repuesto. Compruebe acoplamiento útil y envolvente del portapuntas en la carcasa real antes de aprobarlo. Registre revisión de herramienta con tornillo y panel, incluida la especificación de repuestos. La huella restringida no constituye un nivel de seguridad certificado ni un grado de protección del cerramiento.','Per confrontare un ricambio, conservare disegno vite, riferimento impronta e identificativo utensile originale. Verificare impegno utile e ingombro del portainserto nell’involucro reale prima dell’approvazione. Registrare revisione dell’utensile con vite e pannello, compresa la specifica dei ricambi. La geometria speciale non equivale a un livello di sicurezza certificato o a un grado di protezione dell’involucro.','Conservez plan de vis, référence d’empreinte et identification de l’outil initial pour comparer un remplacement. Vérifiez engagement utile et encombrement du porte-embout dans le boîtier réel avant approbation. Consignez indice d’outil, configuration de vis et panneau, et spécification des rechanges. L’empreinte spéciale ne constitue ni un niveau de sécurité certifié ni un indice de protection du boîtier.','比较替换工具时，保留螺丝图纸、槽型依据和原工具标识。批准前在实际外壳内检查有效啮合与夹持器外形空间，将维修工具版本与螺丝、面板组合一起记录，并明确替换工具的规格。特殊驱动几何本身不等于独立认证的安全等级，也不等于外壳防护等级。');
put('securityNext','Antrieb und Werkzeugzugang im Einbau gemeinsam prüfen','Revisar juntos la huella y el acceso de la herramienta instalada','Valutare insieme impronta e accesso dell’utensile montato','Examiner ensemble empreinte et accès de l’outil en place','将槽型与装机工具空间一起评审');

put('machineryMetaTitle','Sonderstehbolzen und Befestiger für Maschinenbaugruppen','Espárragos y fijaciones a medida para maquinaria','Prigionieri e fissaggi su misura per macchinari','Goujons et fixations sur mesure pour machines','机械装配非标螺柱与紧固件：接口、安装及验收');
put('machineryMeta','Stehbolzen mit unterschiedlichen Gewinden, Nutenköpfe und Gelenkbefestiger vergleichen. Gegenstückgeometrie, Einbaufolge und Versionsnachweise festlegen.','Compare espárragos de roscas distintas, cabezas cautivas en ranura y uniones articuladas. Defina geometría acoplada, montaje y registros de revisión.','Confrontare prigionieri con filetti diversi, teste vincolate in cava e collegamenti articolati. Definire geometria, montaggio e revisioni.','Comparez goujons à filetages différents, têtes retenues en rainure et fixations d’articulation. Définissez géométrie, montage et suivi des indices.','比较两端异牙螺柱、槽内捕获头部与活动连接件，分别明确配合几何、安装顺序和版本记录。');
put('machineryTitle','Verbindung nach Einbau und Lastübertragung auswählen','Elegir la unión según montaje y transmisión de carga','Scegliere il collegamento secondo montaggio e trasferimento del carico','Choisir la liaison selon montage et transfert de charge','按安装方式与载荷传递选择连接结构');
put('machineryIntro','Ein Stehbolzen zwischen unterschiedlichen Gewinden, ein gefangener Nutenkopf und ein Bolzengelenk brauchen unterschiedliche Zeichnungsangaben. Vor der Fertigungsroute die Gegenstückschnittstellen und Montagefolge klären.','Un espárrago entre piezas roscadas, una cabeza capturada en ranura y un componente articulado por pasador necesitan planos distintos. Empiece por interfaces y montaje antes de elegir proceso.','Un prigioniero fra pezzi filettati, una testa vincolata in cava e un elemento articolato con perno richiedono disegni diversi. Partire da interfacce e sequenza di montaggio prima del ciclo produttivo.','Un goujon entre deux pièces filetées, une tête retenue en rainure et un composant articulé par axe demandent des indications différentes. Partez des interfaces et du montage avant de choisir le procédé.','连接两个螺纹件的螺柱、卡在槽内的头部，以及通过销轴活动的组件，对图纸的要求不同。选择工艺路线前，先明确配合接口和装配顺序。');
put('machineryOne','Unterschiedliche Gewindeschnittstellen verbinden','Conectar interfaces de rosca distintas','Collegare interfacce filettate diverse','Relier des interfaces filetées différentes','连接不同的螺纹接口');
put('machineryOneSpec','Stehbolzenenden A und B mit Gewindesystem, Steigung, nutzbarer Länge und Eingriffsanforderung kennzeichnen. Schultern und Werkzeugzugang dazwischen zeigen.','Identifique extremos A y B con sistema de rosca, paso, longitud útil y acoplamiento requerido. Muestre hombros o acceso de herramienta entre ellos.','Identificare estremità A e B con sistema di filettatura, passo, lunghezza utile e impegno richiesto. Indicare spallamenti o accesso utensile intermedi.','Repérez extrémités A et B avec système de filetage, pas, longueur utile et engagement requis. Montrez épaulements ou accès d’outil intermédiaires.','将螺柱两端标为 A 和 B，分别注明牙制、螺距、有效长度和旋合要求，并标出中间的台阶或工具操作结构。');
put('machineryOneCheck','Jedes Ende nach bestellter Oberflächenbehandlung gegen seine eigene Vorgabe lehren. Endkennzeichnung in Prüf- und Montagenachweisen beibehalten.','Verifique cada extremo según su especificación tras el acabado pedido. Mantenga la identificación de extremos en inspección y montaje.','Controllare ciascuna estremità con la propria specifica dopo la finitura ordinata. Conservare l’identificazione nei documenti di controllo e montaggio.','Contrôlez chaque extrémité selon sa spécification après la finition commandée. Gardez son identification dans les contrôles et le montage.','按订购的最终表面状态，用各端自己的规格检查螺纹，并在检验与装配记录中保留端部标识。');
put('machineryTwo','Kopf in einer Befestigungsnut fangen','Capturar una cabeza en una ranura de montaje','Vincolare una testa in una cava di montaggio','Retenir une tête dans une rainure de montage','将头部约束在安装槽内');
put('machineryTwoSpec','Tatsächliche Nut- und Taschengeometrie, Kopfausrichtung, Auflage und Einführweg definieren. Klemmstapel und Werkzeugzugang vollständig einbeziehen.','Defina ranura y alojamiento reales, orientación de cabeza, apoyo e inserción. Incluya cadena completa de apriete y acceso de herramienta.','Definire geometria reale di cava e sede, orientamento testa, appoggio e inserimento. Includere pacco serrato completo e accesso utensile.','Définissez géométrie réelle de rainure et logement, orientation de tête, appui et insertion. Incluez empilage serré et accès d’outil.','定义真实槽与头部容纳空间、头部方向、承压面和装入路线，提供完整夹紧叠层及工具空间。');
put('machineryTwoCheck','Einführen und Anziehen in der vorgesehenen Nut erproben. Anlage und erforderliche Verdrehsicherung prüfen, ohne gleiche Querschnitte aller Profilnuten vorauszusetzen.','Pruebe inserción y apriete en la ranura prevista. Confirme asiento y antigiro sin suponer que todas las ranuras de perfil tienen la misma sección.','Provare inserimento e serraggio nella cava prevista. Confermare appoggio e antirotazione senza presumere che tutte le cave dei profilati abbiano la stessa sezione.','Essayez insertion et serrage dans la rainure prévue. Confirmez appui et antirotation sans supposer une section identique pour toutes les rainures de profilés.','在预定槽内试装和锁紧，确认落座与所需防转功能，不能默认所有型材槽截面都相同。');
put('machineryThree','Bewegliches Gestänge verbinden','Unir un mecanismo articulado','Collegare un cinematismo mobile','Assembler une liaison mobile','连接活动连杆');
put('machineryThreeSpec','Auge oder Gabel, Gegenbolzen, Bewegungsfreiraum und Lastrichtung zeigen. Gewindeeingriff und Sicherung des Gelenks definieren.','Muestre ojo u horquilla, pasador, espacio de articulación y dirección de carga. Defina acoplamiento de rosca y retención de la unión.','Indicare occhio o forcella, perno accoppiato, spazio di articolazione e direzione del carico. Definire impegno e ritegno del giunto.','Montrez œil ou fourche, axe en regard, débattement et direction de charge. Définissez engagement du filetage et retenue de la liaison.','标出环孔或叉头、配合销轴、活动空间及载荷方向，规定旋合长度与连接保持方式。');
put('machineryThreeCheck','Bolzenschnittstelle und Bewegungsraum prüfen, dann geforderte Gelenkprüfungen vereinbaren. Ein Gelenkauge ist nicht automatisch ein freigegebenes Anschlagmittel.','Compruebe interfaz del pasador y movimiento y acuerde los ensayos de unión exigidos. Un ojo de articulación no es automáticamente un accesorio de elevación aprobado.','Controllare interfaccia del perno e ingombro di movimento, poi concordare le prove richieste. Un occhio di articolazione non è automaticamente un attacco di sollevamento approvato.','Contrôlez interface d’axe et débattement, puis convenez des essais prescrits. Un œil d’articulation n’est pas automatiquement un point de levage approuvé.','检查销轴配合与运动范围，再约定所需连接试验。活动连接用环孔不能自动当作已批准的吊装点。');
put('machineryCaseTitle','Änderungsbeispiel: Stehbolzen mit unterschiedlichen Gewinden ändern','Ejemplo de cambio: revisar un espárrago de roscas distintas','Esempio di modifica: aggiornare un prigioniero con filetti diversi','Exemple de modification : réviser un goujon à filetages différents','变更示例：修改两端异牙螺柱');
put('machineryCase','Die Änderung eines Endes kann Kennzeichnung und Einbau beeinflussen, auch wenn das andere Ende gleich bleibt. Beide Gegenstücke, Schulterlage, Werkzeugzugang und Endoberfläche mit der geänderten Zeichnung vergleichen. Auflisten, welche endbezogenen Lehren und Montageprüfungen sich ändern; die bisherige Freigabe bleibt ihrem ursprünglichen Stand zugeordnet. Vor Wiederholbestellungen den neuen Musterumfang vereinbaren.','Cambiar un extremo puede afectar identificación y montaje aunque el otro siga igual. Compare ambas piezas acopladas, posición del hombro, acceso y acabado final con el plano revisado. Liste qué calibres y controles por extremo deben cambiar y vincule la aprobación anterior a su revisión original. Acuerde el alcance de muestras antes de repetir cantidades.','La modifica di un’estremità può influire su identificazione e montaggio anche se l’altra resta uguale. Confrontare entrambi i pezzi accoppiati, spallamento, accesso e finitura con il disegno aggiornato. Elencare calibri e controlli da modificare per estremità, mantenendo l’approvazione precedente associata alla revisione originale. Concordare i nuovi campioni prima dei riordini.','Modifier une extrémité peut affecter identification et montage même si l’autre reste identique. Comparez les deux pièces en regard, position d’épaulement, accès et finition au plan révisé. Listez calibres et contrôles à modifier par extrémité, en conservant l’ancienne approbation liée à son indice initial. Convenez des nouveaux échantillons avant les commandes répétées.','即使另一端保持不变，修改一端也可能影响零件识别和安装。按新图纸比较两侧配合件、台阶位置、工具空间及最终表面状态，列出哪些端部专用量规和装配检查需要调整。旧批准记录继续对应原版本，重复订购前先约定新版样品的检查范围。');
put('machineryNext','Beide Enden eines Sonderstehbolzens identifizieren und prüfen','Identificar e inspeccionar ambos extremos de un espárrago a medida','Identificare e controllare entrambe le estremità di un prigioniero','Identifier et contrôler les deux extrémités d’un goujon sur mesure','明确非标螺柱两端的标识与检查');

export function applyIndustryInterfaceReview(){
 Object.assign(review,{
  'Defined drive profiles':{de:'Definierte Antriebsprofile',es:'Perfiles de accionamiento definidos',it:'Profili dell’impronta definiti',fr:'Profils d’empreinte définis',zh:'明确槽型轮廓'},
  'Supply the exact recess and matching tool requirement, including center-pin details where used.':{de:'Geben Sie die genaue Antriebsvertiefung und das passende Werkzeug an, gegebenenfalls einschließlich der Mittelstiftgeometrie.',es:'Defina el perfil exacto de la huella y la herramienta compatible, incluidos los detalles del tetón central cuando corresponda.',it:'Specificare la geometria esatta dell’impronta e l’utensile compatibile, compreso l’eventuale perno centrale.',fr:'Précisez le profil exact de l’empreinte et l’outil compatible, y compris la géométrie du téton central le cas échéant.',zh:'提供准确的驱动槽型与配套工具要求，采用带柱结构时注明中柱几何。'},
  'Security & Access Equipment':{de:'Sicherheits- und Zugangsausrüstung',es:'Equipos de seguridad y acceso',it:'Attrezzature di sicurezza e accesso',fr:"Équipement de sécurité et d'accès",zh:'安防与门禁设备'},
  'Security & Access Equipment ↗':{de:'Sicherheits- und Zugangsausrüstung ↗',es:'Equipos de seguridad y acceso ↗',it:'Attrezzature di sicurezza e accesso ↗',fr:"Équipement de sécurité et d'accès ↗",zh:'安防与门禁设备 ↗'},
  'Security & Access Equipment — industry overview':{de:'Sicherheits- und Zugangsausrüstung – Branchenüberblick',es:'Equipos de seguridad y acceso — vista general del sector',it:'Attrezzature di sicurezza e accesso — panoramica del settore',fr:"Équipement de sécurité et d'accès — vue d’ensemble du secteur",zh:'安防与门禁设备行业总览'}
 });
 for(const id of Object.keys(industryInterfaceCopy))if(!review[industryInterfaceCopy[id]])throw Error('Missing industry interface translation '+id);
 for(const [id,source]of Object.entries(industryInterfaceCopy))if(id.endsWith('MetaTitle'))review[source+' | ZUFEK']=Object.fromEntries(Object.entries(review[source]).map(([locale,value])=>[locale,value+' | ZUFEK']));
 fs.writeFileSync('translations/industry-interface-review.json',JSON.stringify(review,null,2)+'\n');
 for(const locale of ['de','es','it','fr','zh']){const file='translations/'+locale+'.json',d=JSON.parse(fs.readFileSync(file,'utf8'));for(const [source,values]of Object.entries(review))d[source]=values[locale];fs.writeFileSync(file,JSON.stringify(d,null,2)+'\n');}
 return Object.keys(review).length;
}
if(process.argv[1]?.replaceAll('\\','/').endsWith('/industry-interface-localization.mjs'))console.log('Applied industry interface translations: '+applyIndustryInterfaceReview());
